const bfs = queue => {
  while (queue.length) {
    for (let i = queue.length - 1; 0 <= i; i--) {
      const node = queue.shift();
      const left = node.right;
      const right = node.left;
      node.left = left;
      node.right = right;
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
  }
};

